package com.alibaba.fastjson2.reader;

import com.alibaba.fastjson2.JSON;
import com.alibaba.fastjson2.JSONReader;
import org.junit.jupiter.api.Test;

import java.lang.reflect.Field;
import java.util.Arrays;
import java.util.HashMap;
import java.util.List;
import java.util.Map;

import static org.junit.jupiter.api.Assertions.*;

public class ObjectReaderImplListTest {

    @Test
    public void testInstanceTypeForArraysArrayList() throws Exception {
        Class<?> arraysListClass = Arrays.asList(0).getClass();
        ObjectReader reader = ObjectReaderImplList.of(arraysListClass, arraysListClass, 0);

        Field instanceTypeField = ObjectReaderImplList.class.getDeclaredField("instanceType");
        instanceTypeField.setAccessible(true);
        Class<?> instanceType = (Class<?>) instanceTypeField.get(reader);

        assertEquals(arraysListClass, instanceType,
            "instanceType must be Arrays$ArrayList after patch");
    }
}

